#!/usr/bin/env node
/**
 * Build the read-only SQLite serving database from the prepared JSON artifacts.
 *
 * Source of truth: web/public/data/{multimodal.json,islands.geojson,heigit-baseline.json}
 * Output:         web/server/assets/maldives.sqlite (gitignored; regenerated by dev/build)
 *
 * Usage:
 *   node --experimental-strip-types scripts/build-db.ts
 *   node --experimental-strip-types scripts/build-db.ts --check
 *   node --experimental-strip-types scripts/build-db.ts --output /tmp/test.sqlite
 */
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, statSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { DatabaseSync } from 'node:sqlite'

const HERE = dirname(fileURLToPath(import.meta.url))
const WEB_ROOT = resolve(HERE, '..')
const DEFAULT_SOURCE_DIR = resolve(WEB_ROOT, 'public/data')
const DEFAULT_OUTPUT = resolve(WEB_ROOT, 'server/assets/maldives.sqlite')
const SCHEMA_PATH = resolve(HERE, 'sqlite-schema.sql')
export const SCHEMA_VERSION = 2

/**
 * Analysis tables compiled from web/public/data/extras/<name>.json
 * (scripts/multimodal/build_extras.py). Each file is { meta: { rowCount, ... }, records: [...] }.
 * `idColumn` is generated from the record position where the table has no natural key.
 */
export const EXTRA_TABLES: ReadonlyArray<{ name: string; columns: readonly string[]; idColumn?: string }> = [
  { name: 'fares_air', columns: ['pair', 'origin', 'destination', 'resident_one_way_mvr', 'lowest_mvr', 'confidence', 'basis', 'source_url'] },
  { name: 'fare_models', columns: ['mode', 'a_mvr', 'b_mvr_per_km', 'n', 'r2', 'thin'] },
  {
    name: 'island_profile',
    columns: ['island_id', 'name', 'atoll_code', 'atoll_name', 'population', 'highest_grade', 'school_enrolment', 'higher_secondary_on_island', 'hei_campuses', 'beds_per_1000', 'staff_per_10k', 'evacuations_per_1000', 'aasandha_per_person_mvr'],
  },
  { name: 'health_facilities', columns: ['facility_key', 'name', 'island', 'atoll_code', 'island_id', 'tier', 'grade', 'type', 'level_2026', 'owner'] },
  { name: 'economics', idColumn: 'id', columns: ['kind', 'key', 'value', 'unit', 'year', 'geography', 'note', 'source_url'] },
  {
    name: 'observed_sea_links',
    idColumn: 'id',
    columns: ['from_island_id', 'to_island_id', 'from_name', 'to_name', 'trips_per_day', 'active_days', 'vessels', 'median_min', 'p80_min', 'distance_km', 'speed_class', 'first_dep_hour_p10', 'last_dep_hour_p90', 'rtl_served'],
  },
  {
    name: 'validation_atoll',
    columns: ['atoll_code', 'pop_model', 'n_islands', 'hosp_pct_nodata', 'hosp_pct_noroute_of_covered', 'hosp_pct_noroute_of_total', 'hosp_min_reachable', 'hosp_min_penalised', 'reg_pct_nodata', 'reg_pct_noroute_of_covered', 'reg_pct_noroute_of_total', 'reg_min_reachable', 'reg_min_penalised', 'g1112_pct_nodata', 'g1112_pct_noroute_of_covered', 'g1112_pct_noroute_of_total', 'g1112_min_reachable', 'g1112_min_penalised', 'estimated_air', 'pop2022_resident', 'evacuations_per_1000_2023', 'op_visits_per_capita_2023', 'aasandha_exp_per_capita_2025_mvr', 'inpatient_beds_per_1000', 'pct_16_19_studying', 'maldivian_pop_all_ages', 'hs_attending_residents', 'registered_here_living_in_male', 'male_resident_per_1000_pop', 'g11_12_per_100_16_19', 'is_greater_male'],
  },
  {
    name: 'island_access',
    columns: ['origin_island_id', 'category', 'departure_minute', 'estimated_air', 'status', 'elapsed_minutes', 'modes', 'destination_island_id', 'best_elapsed_minutes'],
  },
]

interface ExtrasFile {
  meta: { rowCount: number; [key: string]: unknown }
  records: Array<Record<string, unknown>>
}

type BuildOptions = { sourceDir?: string; outputPath?: string; extrasDir?: string }

export const EXPECTED = {
  islands: 200,
  origins: 191,
  // Includes the gap-filling layers from scripts/multimodal/augment_network.py:
  // 46 MTCC 2023 stops (+46 jetty access edges), 30 MTCC trips (with running days) and 154
  // observed boat links.
  stops: 163,
  airports: 20,
  accessEdges: 199,
  services: 350,
  facilities: 945,
  categories: 48,
  geojsonFeatures: 200,
  hdxNational: 34,
  hdxUnits: 43,
} as const

interface Island {
  id: string
  name: string
  atoll?: string
  atollName?: string
  lat?: number
  lon?: number
  population?: number
  status?: string
  isOrigin?: boolean
}

interface Stop {
  id: string
  code?: string
  name: string
  islandId: string
  lat?: number
  lon?: number
  scheduled?: boolean
}

interface Airport {
  id: string
  iata: string
  name: string
  islandId: string
  lat?: number
  lon?: number
}

interface AccessEdge {
  from: string
  to: string
  mode: string
  minutes: number
  confidence?: string
  basis?: string
  distanceKm?: number
  assumed?: boolean
}

interface ServiceStop {
  stopId: string
  name?: string
  sequence: number
  arrival: number
  departure: number
}

interface Service {
  id: string
  kind: string
  mode: string
  operator?: string
  routeId?: string
  routeCode?: string
  zone?: string
  confidence?: string
  status?: string
  fromNode?: string
  toNode?: string
  stops?: ServiceStop[]
}

interface Facility {
  id: string
  name: string
  islandId: string
  kind: string
  categories: string[]
  tier?: string
  type?: string
  precision: string
  source?: string
  sourceDate?: string
  reviewed?: boolean
}

interface Category {
  id: string
  label: string
  kind: string
  group: string
  definition?: string
  confidenceNote?: string
  source?: string
  facilityCount?: number
  islandCount?: number
}

interface GeoFeature {
  type: 'Feature'
  properties: { islandId: string; name?: string; [key: string]: unknown }
  geometry: unknown
}

interface HdxNational {
  category: string
  threshold: string | number
  share: number
  population: number
}

interface HdxUnit {
  admLevel?: string
  name: string
  category: string
  within5km?: number | null
}

interface Network {
  meta: Record<string, unknown>
  islands: Island[]
  stops: Stop[]
  airports: Airport[]
  accessEdges: AccessEdge[]
  services: Service[]
  facilities: Facility[]
  categories: Category[]
}

interface HdxBaseline {
  source: string
  method: string
  warning: string
  national: HdxNational[]
  units: HdxUnit[]
}

export interface DatabaseSummary {
  outputPath: string
  schemaVersion: number
  counts: {
    islands: number
    stops: number
    airports: number
    accessEdges: number
    services: number
    facilities: number
    categories: number
    facilityCategories: number
    serviceStops: number
    hdxNational: number
    hdxUnits: number
  }
  /** Row counts of the optional analysis tables (0 when the extras files were absent). */
  extras: Record<string, number>
  bytes: number
  digest: string
}

function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, 'utf8')) as T
}

function optionalString(value: string | undefined): string | null {
  return value ?? null
}

function optionalNumber(value: number | undefined): number | null {
  return value ?? null
}

function bool(value: boolean | undefined, fallback = false): number {
  return (value ?? fallback) ? 1 : 0
}

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message)
}

function assertCount(name: string, actual: number, expected: number): void {
  assert(actual === expected, `${name}: expected ${expected}, found ${actual}`)
}

/**
 * Counts the network itself declares (meta.counts, written by augment_network.py) take the place
 * of the hand-edited stops / access edges / services expectations, so the builder checks the
 * database against the network's own manifest instead of numbers that drift.
 */
let expected: { -readonly [K in keyof typeof EXPECTED]: number } = { ...EXPECTED }
/** Network build id (meta.build.id); fares.json and extras must have been built from it. */
let networkBuildId: string | null = null

function useManifest(network: Network): void {
  const counts = (network.meta.counts ?? {}) as Record<string, number>
  expected = {
    ...EXPECTED,
    stops: Number.isFinite(counts.stops) ? counts.stops : EXPECTED.stops,
    accessEdges: Number.isFinite(counts.accessEdges) ? counts.accessEdges : EXPECTED.accessEdges,
    services: Number.isFinite(counts.services) ? counts.services : EXPECTED.services,
  }
  const build = (network.meta as { build?: { id?: string } }).build
  networkBuildId = typeof build?.id === 'string' ? build.id : null
}

function validateSources(network: Network, geojson: { features?: GeoFeature[] }, hdx: HdxBaseline): void {
  useManifest(network)
  assertCount('islands', network.islands.length, expected.islands)
  assertCount('origins', network.islands.filter((island) => island.isOrigin).length, expected.origins)
  assertCount('stops', network.stops.length, expected.stops)
  assertCount('airports', network.airports.length, expected.airports)
  assertCount('access edges', network.accessEdges.length, expected.accessEdges)
  assertCount('services', network.services.length, expected.services)
  assertCount('facilities', network.facilities.length, expected.facilities)
  assertCount('categories', network.categories.length, expected.categories)
  assertCount('geojson features', geojson.features?.length ?? 0, expected.geojsonFeatures)
  assertCount('hdx national rows', hdx.national.length, expected.hdxNational)
  assertCount('hdx unit rows', hdx.units.length, expected.hdxUnits)

  const metaCounts = network.meta.counts as Record<string, number> | undefined
  if (metaCounts) {
    assertCount('meta islands', metaCounts.islands, expected.islands)
    assertCount('meta stops', metaCounts.stops, expected.stops)
    assertCount('meta airports', metaCounts.airports, expected.airports)
    assertCount('meta facilities', metaCounts.facilities, expected.facilities)
    assertCount('meta categories', metaCounts.categories, expected.categories)
  }

  const islandIds = new Set(network.islands.map((island) => island.id))
  const stopIds = new Set(network.stops.map((stop) => stop.id))
  const airportIds = new Set(network.airports.map((airport) => airport.id))
  const categoryIds = new Set(network.categories.map((category) => category.id))
  assert(islandIds.size === network.islands.length, 'duplicate island ids')
  assert(stopIds.size === network.stops.length, 'duplicate stop ids')
  assert(airportIds.size === network.airports.length, 'duplicate airport ids')
  assert(categoryIds.size === network.categories.length, 'duplicate category ids')

  for (const stop of network.stops) {
    assert(islandIds.has(stop.islandId), `stop ${stop.id} points at missing island ${stop.islandId}`)
  }
  for (const airport of network.airports) {
    assert(islandIds.has(airport.islandId), `airport ${airport.id} points at missing island ${airport.islandId}`)
  }
  for (const facility of network.facilities) {
    assert(islandIds.has(facility.islandId), `facility ${facility.id} points at missing island ${facility.islandId}`)
    for (const categoryId of facility.categories) {
      assert(categoryIds.has(categoryId), `facility ${facility.id} points at missing category ${categoryId}`)
    }
  }
  for (const service of network.services) {
    if (service.kind === 'timetabled') {
      assert(Array.isArray(service.stops) && service.stops.length > 0, `service ${service.id} has no stops`)
      for (const stop of service.stops!) {
        assert(stopIds.has(stop.stopId), `service ${service.id} points at missing stop ${stop.stopId}`)
      }
    }
  }

  const featureIslands = new Set((geojson.features ?? []).map((feature) => feature.properties.islandId))
  assert(featureIslands.size === expected.geojsonFeatures, 'geojson features do not have unique island ids')
  for (const islandId of islandIds) {
    assert(featureIslands.has(islandId), `island ${islandId} has no geojson feature`)
  }
}

function readExtras(extrasDir: string): Map<string, ExtrasFile> {
  const loaded = new Map<string, ExtrasFile>()
  if (!existsSync(extrasDir)) {
    console.log(`build-db: extras directory not found (${extrasDir}); skipping analysis tables`)
    return loaded
  }
  for (const spec of EXTRA_TABLES) {
    const path = resolve(extrasDir, `${spec.name}.json`)
    if (!existsSync(path)) {
      console.log(`build-db: extras/${spec.name}.json not found; skipping table ${spec.name}`)
      continue
    }
    const file = readJson<ExtrasFile>(path)
    assert(Array.isArray(file.records), `extras/${spec.name}.json: records must be an array`)
    assertCount(`extras ${spec.name} (meta.rowCount)`, file.records.length, Number(file.meta?.rowCount))
    const extrasBuild = (file.meta as { networkBuildId?: string } | undefined)?.networkBuildId
    assert(
      !networkBuildId || !extrasBuild || extrasBuild === networkBuildId,
      `extras/${spec.name}.json was built from network ${extrasBuild}, but multimodal.json is ${networkBuildId}; re-run scripts/multimodal/build_extras.py`,
    )
    loaded.set(spec.name, file)
  }
  return loaded
}

function extraValue(value: unknown): string | number | null {
  if (value === undefined || value === null) return null
  if (typeof value === 'boolean') return value ? 1 : 0
  if (typeof value === 'number' || typeof value === 'string') return value
  return JSON.stringify(value)
}

function insertExtras(db: DatabaseSync, loaded: Map<string, ExtrasFile>): void {
  for (const spec of EXTRA_TABLES) {
    const file = loaded.get(spec.name)
    if (!file) continue
    const columns = spec.idColumn ? [spec.idColumn, ...spec.columns] : [...spec.columns]
    const insert = db.prepare(
      `INSERT INTO ${spec.name} (${columns.join(', ')}) VALUES (${columns.map(() => '?').join(', ')})`,
    )
    file.records.forEach((record, index) => {
      const values = spec.columns.map((column) => extraValue(record[column]))
      insert.run(...(spec.idColumn ? [index + 1, ...values] : values))
    })
    db.prepare('INSERT INTO extras_meta (name, row_count, generated_at, payload_json) VALUES (?, ?, ?, ?)').run(
      spec.name,
      file.records.length,
      typeof file.meta.generatedAt === 'string' ? file.meta.generatedAt : null,
      JSON.stringify(file.meta),
    )
  }
}

function featureMap(geojson: { features?: GeoFeature[] }): Map<string, GeoFeature> {
  return new Map((geojson.features ?? []).map((feature) => [feature.properties.islandId, feature]))
}

function buildDatabaseInternal(options: BuildOptions = {}): DatabaseSummary {
  const sourceDir = options.sourceDir ?? DEFAULT_SOURCE_DIR
  const extrasDir = options.extrasDir ?? resolve(sourceDir, 'extras')
  const outputPath = options.outputPath ?? DEFAULT_OUTPUT
  const networkPath = resolve(sourceDir, 'multimodal.json')
  const geojsonPath = resolve(sourceDir, 'islands.geojson')
  const hdxPath = resolve(sourceDir, 'heigit-baseline.json')

  for (const path of [networkPath, geojsonPath, hdxPath, SCHEMA_PATH]) {
    assert(existsSync(path), `missing required file: ${path}`)
  }

  const network = readJson<Network>(networkPath)
  const geojson = readJson<{ features?: GeoFeature[] }>(geojsonPath)
  const hdx = readJson<HdxBaseline>(hdxPath)
  validateSources(network, geojson, hdx)
  const extras = readExtras(extrasDir)

  mkdirSync(dirname(outputPath), { recursive: true })
  const temporaryPath = `${outputPath}.tmp-${process.pid}`
  rmSync(temporaryPath, { force: true })

  const db = new DatabaseSync(temporaryPath)
  try {
    db.exec(readFileSync(SCHEMA_PATH, 'utf8'))
    db.exec('PRAGMA foreign_keys = ON')
    db.exec('PRAGMA synchronous = OFF')
    db.exec('PRAGMA journal_mode = MEMORY')
    db.exec('BEGIN IMMEDIATE')

    db.prepare(
      'INSERT INTO meta (id, schema_version, generated_at, reference_day, payload_json) VALUES (1, ?, ?, ?, ?)',
    ).run(
      SCHEMA_VERSION,
      typeof network.meta.generatedAt === 'string' ? network.meta.generatedAt : null,
      typeof network.meta.referenceDay === 'string' ? network.meta.referenceDay : null,
      JSON.stringify(network.meta),
    )

    const insertIsland = db.prepare(
      `INSERT INTO islands
        (id, ordinal, name, atoll_code, atoll_name, lat, lon, population, status, is_origin, payload_json, feature_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    const features = featureMap(geojson)
    network.islands.forEach((island, ordinal) => {
      const feature = features.get(island.id)
      assert(feature, `missing geojson feature for island ${island.id}`)
      insertIsland.run(
        island.id,
        ordinal,
        island.name,
        optionalString(island.atoll),
        optionalString(island.atollName),
        optionalNumber(island.lat),
        optionalNumber(island.lon),
        optionalNumber(island.population),
        optionalString(island.status),
        bool(island.isOrigin),
        JSON.stringify(island),
        JSON.stringify(feature),
      )
    })

    const insertStop = db.prepare(
      `INSERT INTO stops (id, ordinal, code, name, island_id, lat, lon, scheduled, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    network.stops.forEach((stop, ordinal) => {
      insertStop.run(
        stop.id,
        ordinal,
        optionalString(stop.code),
        stop.name,
        stop.islandId,
        optionalNumber(stop.lat),
        optionalNumber(stop.lon),
        bool(stop.scheduled),
        JSON.stringify(stop),
      )
    })

    const insertAirport = db.prepare(
      `INSERT INTO airports (id, ordinal, iata, name, island_id, lat, lon, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    network.airports.forEach((airport, ordinal) => {
      insertAirport.run(
        airport.id,
        ordinal,
        airport.iata,
        airport.name,
        airport.islandId,
        optionalNumber(airport.lat),
        optionalNumber(airport.lon),
        JSON.stringify(airport),
      )
    })

    const insertAccess = db.prepare(
      `INSERT INTO access_edges
        (ordinal, from_node, to_node, mode, minutes, confidence, basis, distance_km, assumed, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    network.accessEdges.forEach((edge, ordinal) => {
      insertAccess.run(
        ordinal,
        edge.from,
        edge.to,
        edge.mode,
        edge.minutes,
        optionalString(edge.confidence),
        optionalString(edge.basis),
        optionalNumber(edge.distanceKm),
        bool(edge.assumed),
        JSON.stringify(edge),
      )
    })

    const insertService = db.prepare(
      `INSERT INTO services
        (id, ordinal, kind, mode, operator, route_id, route_code, zone, confidence, status, from_node, to_node, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    const insertServiceStop = db.prepare(
      `INSERT INTO service_stops (service_id, sequence, stop_id, arrival, departure)
       VALUES (?, ?, ?, ?, ?)`,
    )
    network.services.forEach((service, ordinal) => {
      insertService.run(
        service.id,
        ordinal,
        service.kind,
        service.mode,
        optionalString(service.operator),
        optionalString(service.routeId),
        optionalString(service.routeCode),
        optionalString(service.zone),
        optionalString(service.confidence),
        optionalString(service.status),
        optionalString(service.fromNode),
        optionalString(service.toNode),
        JSON.stringify(service),
      )
      for (const stop of service.stops ?? []) {
        insertServiceStop.run(service.id, stop.sequence, stop.stopId, stop.arrival, stop.departure)
      }
    })

    const insertCategory = db.prepare(
      `INSERT INTO categories
        (id, ordinal, label, kind, group_name, definition, confidence_note, source, facility_count, island_count, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    network.categories.forEach((category, ordinal) => {
      insertCategory.run(
        category.id,
        ordinal,
        category.label,
        category.kind,
        category.group,
        optionalString(category.definition),
        optionalString(category.confidenceNote),
        optionalString(category.source),
        optionalNumber(category.facilityCount),
        optionalNumber(category.islandCount),
        JSON.stringify(category),
      )
    })

    const insertFacility = db.prepare(
      `INSERT INTO facilities
        (id, ordinal, name, island_id, kind, tier, type, precision, source, source_date, reviewed, payload_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
    const insertFacilityCategory = db.prepare(
      'INSERT INTO facility_categories (facility_id, category_id) VALUES (?, ?)',
    )
    network.facilities.forEach((facility, ordinal) => {
      insertFacility.run(
        facility.id,
        ordinal,
        facility.name,
        facility.islandId,
        facility.kind,
        optionalString(facility.tier),
        optionalString(facility.type),
        facility.precision,
        optionalString(facility.source),
        optionalString(facility.sourceDate),
        bool(facility.reviewed),
        JSON.stringify(facility),
      )
      for (const categoryId of facility.categories) {
        insertFacilityCategory.run(facility.id, categoryId)
      }
    })

    db.prepare('INSERT INTO hdx_meta (id, payload_json) VALUES (1, ?)').run(
      JSON.stringify({ source: hdx.source, method: hdx.method, warning: hdx.warning }),
    )
    const insertHdxNational = db.prepare(
      `INSERT INTO hdx_national (ordinal, category, threshold, share, population, payload_json)
       VALUES (?, ?, ?, ?, ?, ?)`,
    )
    hdx.national.forEach((row, ordinal) => {
      insertHdxNational.run(
        ordinal,
        row.category,
        String(row.threshold),
        row.share,
        row.population,
        JSON.stringify(row),
      )
    })
    const insertHdxUnit = db.prepare(
      `INSERT INTO hdx_units (ordinal, adm_level, name, category, within5km, payload_json)
       VALUES (?, ?, ?, ?, ?, ?)`,
    )
    hdx.units.forEach((row, ordinal) => {
      insertHdxUnit.run(
        ordinal,
        optionalString(row.admLevel),
        row.name,
        row.category,
        row.within5km === null || row.within5km === undefined ? null : row.within5km,
        JSON.stringify(row),
      )
    })

    insertExtras(db, extras)

    db.exec('COMMIT')
    const integrity = db.prepare('PRAGMA integrity_check').get() as
      | { integrity_check?: string }
      | undefined
    assert(
      String(integrity?.integrity_check ?? '').toLowerCase() === 'ok',
      `integrity_check failed: ${JSON.stringify(integrity)}`,
    )
    const fkRows = db.prepare('PRAGMA foreign_key_check').all()
    assert(fkRows.length === 0, `foreign_key_check found ${fkRows.length} row(s)`)
    db.exec('VACUUM')
  } catch (error) {
    try {
      db.exec('ROLLBACK')
    } catch {
      // transaction may not have started
    }
    db.close()
    rmSync(temporaryPath, { force: true })
    throw error
  }
  db.close()

  renameSync(temporaryPath, outputPath)
  const summary = inspectDatabase(outputPath)
  return { ...summary, outputPath }
}

function tableCounts(db: DatabaseSync): DatabaseSummary['counts'] {
  const count = (table: string): number => {
    const row = db.prepare(`SELECT count(*) AS count FROM ${table}`).get() as { count: number }
    return Number(row.count)
  }
  return {
    islands: count('islands'),
    stops: count('stops'),
    airports: count('airports'),
    accessEdges: count('access_edges'),
    services: count('services'),
    facilities: count('facilities'),
    categories: count('categories'),
    facilityCategories: count('facility_categories'),
    serviceStops: count('service_stops'),
    hdxNational: count('hdx_national'),
    hdxUnits: count('hdx_units'),
  }
}

/** Row counts per analysis table; verifies each table matches the row count recorded in extras_meta. */
function extraCounts(db: DatabaseSync): Record<string, number> {
  const counts: Record<string, number> = {}
  const recorded = new Map(
    (db.prepare('SELECT name, row_count FROM extras_meta').all() as Array<{ name: string; row_count: number }>).map(
      (row) => [row.name, Number(row.row_count)],
    ),
  )
  for (const spec of EXTRA_TABLES) {
    const row = db.prepare(`SELECT count(*) AS count FROM ${spec.name}`).get() as { count: number }
    counts[spec.name] = Number(row.count)
    assertCount(`extras ${spec.name}`, counts[spec.name], recorded.get(spec.name) ?? 0)
  }
  return counts
}

function digestFile(path: string): string {
  return createHash('sha256').update(readFileSync(path)).digest('hex')
}

function inspectDatabase(outputPath: string): Omit<DatabaseSummary, 'outputPath'> {
  const db = new DatabaseSync(outputPath, { readOnly: true })
  try {
    const versionRow = db.prepare('PRAGMA user_version').get() as { user_version?: number }
    const schemaVersion = Number(versionRow.user_version ?? 0)
    assert(schemaVersion === SCHEMA_VERSION, `unsupported schema user_version ${schemaVersion}`)
    const counts = tableCounts(db)
    assertCount('islands', counts.islands, EXPECTED.islands)
    assertCount('stops', counts.stops, expected.stops)
    assertCount('airports', counts.airports, EXPECTED.airports)
    assertCount('access edges', counts.accessEdges, expected.accessEdges)
    assertCount('services', counts.services, expected.services)
    assertCount('facilities', counts.facilities, EXPECTED.facilities)
    assertCount('categories', counts.categories, EXPECTED.categories)
    assertCount('hdx national rows', counts.hdxNational, EXPECTED.hdxNational)
    assertCount('hdx unit rows', counts.hdxUnits, EXPECTED.hdxUnits)
    const extras = extraCounts(db)
    return {
      schemaVersion,
      counts,
      extras,
      bytes: statSync(outputPath).size,
      digest: digestFile(outputPath),
    }
  } finally {
    db.close()
  }
}

function readPayloads(db: DatabaseSync, table: string, orderColumn = 'ordinal'): unknown[] {
  return (db.prepare(`SELECT payload_json FROM ${table} ORDER BY ${orderColumn}`).all() as Array<{
    payload_json: string
  }>).map((row) => JSON.parse(row.payload_json) as unknown)
}

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`
  if (value && typeof value === 'object') {
    const record = value as Record<string, unknown>
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonical(record[key])}`)
      .join(',')}}`
  }
  return JSON.stringify(value)
}

function assertPayloadEqual(label: string, source: unknown, actual: unknown): void {
  assert(canonical(source) === canonical(actual), `${label}: database payload does not match source JSON`)
}

function checkDatabaseInternal(options: BuildOptions = {}): DatabaseSummary {
  const sourceDir = options.sourceDir ?? DEFAULT_SOURCE_DIR
  const extrasDir = options.extrasDir ?? resolve(sourceDir, 'extras')
  const outputPath = options.outputPath ?? DEFAULT_OUTPUT
  assert(existsSync(outputPath), `database not found: ${outputPath}; run build-db first`)
  assert(existsSync(resolve(sourceDir, 'multimodal.json')), `missing source: ${resolve(sourceDir, 'multimodal.json')}`)
  assert(existsSync(resolve(sourceDir, 'islands.geojson')), `missing source: ${resolve(sourceDir, 'islands.geojson')}`)
  assert(existsSync(resolve(sourceDir, 'heigit-baseline.json')), `missing source: ${resolve(sourceDir, 'heigit-baseline.json')}`)

  const network = readJson<Network>(resolve(sourceDir, 'multimodal.json'))
  const geojson = readJson<{ features?: GeoFeature[] }>(resolve(sourceDir, 'islands.geojson'))
  const hdx = readJson<HdxBaseline>(resolve(sourceDir, 'heigit-baseline.json'))
  validateSources(network, geojson, hdx)

  const db = new DatabaseSync(outputPath, { readOnly: true })
  try {
    const versionRow = db.prepare('PRAGMA user_version').get() as { user_version?: number }
    assert(Number(versionRow.user_version ?? 0) === SCHEMA_VERSION, 'unsupported schema user_version')
    const integrity = db.prepare('PRAGMA integrity_check').get() as
      | { integrity_check?: string }
      | undefined
    assert(
      String(integrity?.integrity_check ?? '').toLowerCase() === 'ok',
      'integrity_check failed',
    )
    const fkRows = db.prepare('PRAGMA foreign_key_check').all()
    assert(fkRows.length === 0, `foreign_key_check found ${fkRows.length} row(s)`)

    const metaRow = db.prepare('SELECT payload_json FROM meta WHERE id = 1').get() as
      | { payload_json: string }
      | undefined
    assert(metaRow, 'meta row missing')
    assertPayloadEqual('meta', network.meta, JSON.parse(metaRow.payload_json))

    assertPayloadEqual('islands', network.islands, readPayloads(db, 'islands'))
    assertPayloadEqual('stops', network.stops, readPayloads(db, 'stops'))
    assertPayloadEqual('airports', network.airports, readPayloads(db, 'airports'))
    assertPayloadEqual('accessEdges', network.accessEdges, readPayloads(db, 'access_edges'))
    assertPayloadEqual('services', network.services, readPayloads(db, 'services'))
    assertPayloadEqual('facilities', network.facilities, readPayloads(db, 'facilities'))
    assertPayloadEqual('categories', network.categories, readPayloads(db, 'categories'))

    const features = (db
      .prepare('SELECT feature_json FROM islands ORDER BY ordinal')
      .all() as Array<{ feature_json: string }>).map((row) => JSON.parse(row.feature_json) as GeoFeature)
    const byIsland = (items: GeoFeature[]): GeoFeature[] =>
      [...items].sort((a, b) => a.properties.islandId.localeCompare(b.properties.islandId))
    assertPayloadEqual('islands.geojson', byIsland(geojson.features ?? []), byIsland(features))

    const hdxMeta = db.prepare('SELECT payload_json FROM hdx_meta WHERE id = 1').get() as
      | { payload_json: string }
      | undefined
    assert(hdxMeta, 'hdx meta missing')
    assertPayloadEqual(
      'hdx.meta',
      { source: hdx.source, method: hdx.method, warning: hdx.warning },
      JSON.parse(hdxMeta.payload_json),
    )
    assertPayloadEqual('hdx.national', hdx.national, readPayloads(db, 'hdx_national'))
    assertPayloadEqual('hdx.units', hdx.units, readPayloads(db, 'hdx_units'))

    const serviceStopCount = db.prepare('SELECT count(*) AS count FROM service_stops').get() as {
      count: number
    }
    const expectedServiceStops = network.services.reduce(
      (sum, service) => sum + (service.stops?.length ?? 0),
      0,
    )
    assertCount('service stops', Number(serviceStopCount.count), expectedServiceStops)

    const associations = db
      .prepare('SELECT facility_id, category_id FROM facility_categories')
      .all() as Array<{ facility_id: string; category_id: string }>
    const expectedAssociations = network.facilities.reduce(
      (sum, facility) => sum + facility.categories.length,
      0,
    )
    assertCount('facility categories', associations.length, expectedAssociations)

    // Analysis tables: every extras file present on disk must be fully loaded with the row count in its meta.
    for (const [name, file] of readExtras(extrasDir)) {
      const row = db.prepare(`SELECT count(*) AS count FROM ${name}`).get() as { count: number }
      assertCount(`extras ${name} vs source file`, Number(row.count), file.records.length)
    }
  } finally {
    db.close()
  }

  return { ...inspectDatabase(outputPath), outputPath }
}

export function buildDatabase(options: BuildOptions = {}): DatabaseSummary {
  return buildDatabaseInternal(options)
}

export function checkDatabase(options: BuildOptions = {}): DatabaseSummary {
  return checkDatabaseInternal(options)
}

function argumentValue(flag: string): string | undefined {
  const index = process.argv.indexOf(flag)
  return index >= 0 ? process.argv[index + 1] : undefined
}

const isMain =
  process.argv[1] !== undefined && pathToFileURL(process.argv[1]).href === import.meta.url

if (isMain) {
  const outputPath = argumentValue('--output') ?? DEFAULT_OUTPUT
  const check = process.argv.includes('--check')
  try {
    const summary = check
      ? checkDatabase({ outputPath })
      : buildDatabase({ outputPath })
    console.log(
      JSON.stringify(
        {
          mode: check ? 'check' : 'build',
          outputPath: summary.outputPath,
          schemaVersion: summary.schemaVersion,
          counts: summary.counts,
          extras: summary.extras,
          bytes: summary.bytes,
          digest: summary.digest,
        },
        null,
        2,
      ),
    )
  } catch (error) {
    console.error(`build-db: ${error instanceof Error ? error.message : String(error)}`)
    process.exitCode = 1
  }
}
